extern int __VERIFIER_nondet_int();
extern void abort(void);
void assume_abort_if_not(int cond) {
  if(!cond) {abort();}
}

#include<pthread.h>
#include<stdlib.h>
#include<stdio.h>

struct s {
  int datum;
  struct s *next;
};

struct s *new(int x) {
  struct s *p = malloc(sizeof(struct s));
  p->datum = x;
  p->next = NULL;
  return p;
}

void list_add(struct s *node, struct s *list) {
  __ikos_print_values("list base", list);
  struct s *temp = list->next;
  __ikos_print_values("next loaded", temp);
  list->next = node;
  node->next = temp;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
struct s *slot[10];

void *t_fun(void *arg) {
  int i = __VERIFIER_nondet_int();
  assume_abort_if_not(0 <= i && i < 10);
  pthread_mutex_lock(&mutex);
  list_add(new(3), slot[i]);
  pthread_mutex_unlock(&mutex);
  return NULL;
}

int main () {
  int j = __VERIFIER_nondet_int();
  assume_abort_if_not(0 <= j && j < 10);
  pthread_t t1;
  struct s *p;

  for (int k = 0; k < 10; k++) {
    slot[k] = new(1);
    struct s *current = slot[k];
    __ikos_print_values("array loaded", current);
    list_add(new(2), current);
  }

  pthread_create(&t1, NULL, t_fun, NULL);

  pthread_mutex_lock(&mutex);
  struct s *current = slot[j];
  __ikos_print_values("main array loaded", current);
  p = current->next; // NORACE
  printf("%d\n", p->datum);
  pthread_mutex_unlock(&mutex);
  return 0;
}

